package com.procurement.quotationcomparison.entity;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;@Entity@Table(name="comparison_criteria",uniqueConstraints=@UniqueConstraint(columnNames={"comparison_id","criteria_name"}))@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class ComparisonCriteria{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="criteria_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="comparison_id",nullable=false)private QuotationComparison comparison;@Column(name="criteria_name",nullable=false,length=80)private String criteriaName;@Column(name="weight_percentage",nullable=false,precision=5,scale=2)private BigDecimal weightPercentage;@Column(length=500)private String description;}
